		TasksRunning:    s.tasks.Running(),
		TasksDropped:    s.tasks.Dropped(),
		Activity:        nil,
		ActivityShown:   0,
		ActivityTotal:   0,
		ActivityDropped: s.toolLog.Dropped(),
		Events:          s.events.Recent(dashboardActivityLimit),
		EventsShown:     0,
		EventsTotal:     s.events.Count(),
		EventsDropped:   s.events.Dropped(),
		Exchanges:       exchanges,
		Messages:        messages,
