// projection of those same bytes. The run step dispatches the held bytes verbatim - the run
// form carries only the review id and token, never re-serialized form fields, so nothing typed
// after the review can change what is written (the collaborator preview spends the same way).
//
// The API key never leaves the server in any direction but the reviewed PUT: it is not in the
// review HTML (the projection redacts it), not in URLs, not in logs, and the key field is a
// password input the live-refresh dirty capture refuses to carry across swaps (app.js).
//
// ui2TriageReviewCap bounds the map so an open-tab pileup cannot grow it without limit. The
// reviewer approved cap 8 with sweep-on-issue: enough for a few open tabs, small enough that a
// full map is a sign to refuse and say so rather than silently drop somebody's review.
const ui2TriageReviewCap = 8

// ui2TriageReview is one minted triage-settings change held for review. The entry dies with the
// gate's ConfirmTTL so a stale review refuses alongside its token, and the run step spends it
// atomically (LoadAndDelete) so a double-confirm cannot dispatch twice.
type ui2TriageReview struct {
	token   string
	body    []byte // the exact minted call body - dispatched verbatim on run
	expires time.Time
}

// ui2TriageBody builds the exact PUT body from the form. A blank key is OMITTED (the API then
// keeps the stored key); the ack is a ui2-local gate, never part of the body.
func ui2TriageBody(enabled bool, baseURL, model, apiKey string) []byte {
	m := map[string]any{"enabled": enabled, "base_url": baseURL, "model": model}
	if apiKey != "" {
		m["api_key"] = apiKey
	}
	b, _ := json.Marshal(m)
	return b
}

// ui2TriageProjection renders the redacted review copy from the exact minted bytes: parse,
// blank the key, re-marshal. The projection is derived from what the token binds, not from a
// second serialization of the form, so the review cannot drift from the dispatch.
func ui2TriageProjection(body []byte) string {
	var m map[string]any
	if err := json.Unmarshal(body, &m); err != nil {
		return "PUT /api/settings/triage (body unreadable for display)"
	}
	if _, has := m["api_key"]; has {
		m["api_key"] = "(hidden - the token binds the exact value you typed)"
	}
	b, _ := json.Marshal(m)
	return "PUT /api/settings/triage\n" + string(b)
}

// ui2ValidateTriageBaseURL rejects base URLs this UI will not mint. Secret-bearing URLs
// (userinfo, query) and fragments are refused here rather than sanitized, because the engine
// appends /chat/completions to the configured value verbatim and the operator should see and
// fix that in the console, not have this page quietly reshape it. Errors name the rejected
// PART, never its value.
func ui2ValidateTriageBaseURL(raw string) string {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return "the base URL is not a full URL (scheme and host are required)"
	}
	// https only for real destinations: the engine sends the configured key as a bearer
	// token with no scheme check of its own, so a remote http:// base URL would put the key on
	// the wire in cleartext. The API itself still accepts http (preexisting behavior, reported
	// separately); THIS page refuses to mint it. Loopback http stays allowed so local synthetic
	// fixtures can exercise the flow in tests and UAT.
	if u.Scheme == "http" {
		h := u.Hostname()
		if ip := net.ParseIP(h); h == "localhost" || (ip != nil && ip.IsLoopback()) {
			return ""
		}
		return "this page only saves https base URLs - http would send the API key in cleartext (loopback http, 127.0.0.1/::1/localhost, is allowed for local testing)"
	}
	if u.Scheme != "https" {
		return "the base URL scheme must be https"
	}
	if u.User != nil {
		return "base URLs with embedded credentials (user:pass@host) are not accepted here - move the credential into the API key field"
	}
	if u.RawQuery != "" {
		return "base URLs with a query string are not accepted here - the endpoint path is appended to the base URL"
	}
	if u.Fragment != "" {
		return "base URLs with a fragment are not accepted here"
	}
	return ""
}

// handleUI2SettingsTriage serves POST /ui2/settings/triage/{action}: confirm mints and renders
// the review; run spends the held entry and dispatches the reviewed bytes.
func (s *Server) handleUI2SettingsTriage(w http.ResponseWriter, r *http.Request) {
	switch r.PathValue("action") {
	case "confirm":
		s.ui2TriageConfirm(w, r)
	case "run":
		s.ui2TriageRun(w, r)
	default:
		http.Error(w, "unknown settings triage action", http.StatusBadRequest)
	}
}

// ui2TriageConfirm validates the form, mints the gate token, holds the exact bytes, and renders
// the review sheet with the redacted projection.
func (s *Server) ui2TriageConfirm(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	fail := func(msg string) {
		model := map[string]any{"error": msg}
		ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_triage_confirm.html", model))
	}
	if s.persist == nil {
		fail("this instance has no project database, so triage settings cannot be saved; start burpsy with -db to persist the project")
		return
	}
	enabled := r.PostFormValue("enabled") != ""
	baseURL := strings.TrimSpace(r.PostFormValue("base_url"))
	model := strings.TrimSpace(r.PostFormValue("model"))
	apiKey := r.PostFormValue("api_key") // password field; never trimmed, never echoed back
	if msg := ui2ValidateTriageBaseURL(baseURL); msg != "" {
		fail(msg)
		return
	}
	// Preserve-changed: a blank key with a CHANGED base URL forwards the stored key to a new
	// destination. That is a credential transfer, so it needs the operator's explicit
	// acknowledgement (the default-unchecked checkbox) before a token is minted - a review
	// sheet warning alone would still have minted a one-click transfer. An unchanged URL is
	// exempt: the key is already going there today.
	if apiKey == "" {
		stored, err := s.persist.LoadTriageSettings()
		if err != nil {
			fail("could not read the current triage settings: " + err.Error())
			return
		}
		// A transfer needs something TO transfer: the ack gate and its warning apply only when
		// a stored key exists. On a fresh configuration a blank key means "no key at all" -
		// saying one would be forwarded would be a false alarm (reviewer catch on 751447d).
		if stored.APIKey != "" && baseURL != stored.BaseURL && r.PostFormValue("allow_key_forward") == "" {
			fail("the base URL changed but no API key was entered: the stored key would be sent to the new URL. Enter a key, revert the URL, or tick the acknowledgement on the form")
			return
		}
	}
	body := ui2TriageBody(enabled, baseURL, model, apiKey)
	// Mint via the gate (the token binds these exact bytes); keep ONLY the token from the
	// mint response - its echoed call body carries the key and is never stored or rendered.
	call, _ := json.Marshal(map[string]any{"method": http.MethodPut, "url": "/api/settings/triage", "body": string(body)})
	mintReq := newReq(http.MethodPost, "/api/settings/triage/confirm")
	mintReq.Header.Set("Content-Type", "application/json")
	mintReq.Body = ioNopCloser(strings.NewReader(string(call)))
	mintRec := newRecorder()
	s.confirmMux.ServeHTTP(mintRec, mintReq)
	var minted struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(mintRec.Body.Bytes(), &minted); err != nil || minted.Token == "" {
		fail("the confirmation gate refused to mint a review - try again")
		return
	}
	id, err := randomHex(16)
	if err != nil {
		fail("review id: " + err.Error())
		return
	}
	// Sweep expired entries on issue, then refuse when the map is still full - a full map
	// means eight open reviews, which is a pileup to surface, not to paper over.
	now := time.Now()
	s.ui2TriageReviews.Range(func(k, v any) bool {
		if e, ok := v.(ui2TriageReview); ok && now.After(e.expires) {
			s.ui2TriageReviews.Delete(k)
		}
		return true
	})
	count := 0
	s.ui2TriageReviews.Range(func(_, _ any) bool { count++; return true })
	if count >= ui2TriageReviewCap {
		fail("too many reviews are open at once - confirm or let some expire, then try again")
		return
	}
	s.ui2TriageReviews.Store(id, ui2TriageReview{token: minted.Token, body: body, expires: now.Add(ConfirmTTL)})
	review := map[string]any{
		"review_id":  id,
		"token":      minted.Token,
		"projection": ui2TriageProjection(body),
		"base_url":   baseURL,
	}
	switch {
	case apiKey != "":
		review["key_replaces"] = true
	default:
		stored, _ := s.persist.LoadTriageSettings()
		if stored.APIKey == "" {
			review["key_absent"] = true
		} else if baseURL != stored.BaseURL {
			review["key_preserves_changed"] = true
			review["old_base_url"] = stored.BaseURL
		} else {
			review["key_preserves_same"] = true
		}
	}
	ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_triage_confirm.html", review))
}

// ui2TriageRun spends the held review entry and dispatches the exact minted bytes with the
// entry's token. The entry is deleted on ANY spend attempt (unknown id, stale, token mismatch,
// dispatch result) so nothing here is replayable.
func (s *Server) ui2TriageRun(w http.ResponseWriter, r *http.Request) {
	_ = r.ParseForm()
	fail := func(msg string) {
		model := map[string]any{"error": msg}
		ui2Fragment(w, r, "burpsy /ui2/ — Settings", "settings", ui2Exec("settings_triage_confirm.html", model))
	}
	if s.persist == nil {
		fail("this instance has no project database, so triage settings cannot be saved; start burpsy with -db to persist the project")
		return
	}
	id := r.PostFormValue("review_id")
	token := r.PostFormValue("token")
	v, ok := s.ui2TriageReviews.LoadAndDelete(id)
	entry, isReview := v.(ui2TriageReview)
	if !ok || !isReview {
		fail("that review is unknown or was already used - review the change again")
		return
	}
	if time.Now().After(entry.expires) {
		fail("that review expired with the confirmation window - review the change again")
		return
	}
	// Both sides are 128-bit random values; compare in constant time anyway so the check never
	// becomes an oracle if the id scheme ever changes.
	if subtle.ConstantTimeCompare([]byte(entry.token), []byte(token)) != 1 {
		fail("that review does not match this confirmation - review the change again")
		return
	}
	// Dispatch the held bytes verbatim. Re-marshaling a decoded map here could produce bytes
	// the gate did not bind, which the gate would (rightly) refuse with a 428.
	req := newReq(http.MethodPut, "/api/settings/triage")
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(ConfirmHeader, token)
	req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
	req.Host = "127.0.0.1"
	req.Header.Set("Origin", "http://127.0.0.1")
	rec := newRecorder()
	s.guarded.ServeHTTP(rec, req)
	if rec.Code == http.StatusPreconditionRequired {
		fail("confirmation required (428) - the review and the dispatch disagree; review again")
		return
	}
	if rec.Code != http.StatusOK {
		// API validation errors are static strings that never echo the key; trim anyway so a
		// future message cannot smear a body across the page.
		fail("the settings API refused the change: " + truncateForDisplay(strings.TrimSpace(rec.Body.String()), 200))
		return
	}
	s.handleUI2Settings(w, r)
}
//
// confirmMux is consulted FIRST and outside the gate entirely. A mint request is itself a mutating
// POST on a gated pattern, so gating it would make the gate unsatisfiable — the one failure mode
// that looks exactly like working, because every dangerous call is refused and nothing can change
// that.
func (s *Server) confirmationGate(h, confirmMux http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// The mint endpoint is matched FIRST and independently of the risk resolution below.
		//
		// Checking it after is a real bug, not a style preference: a request for
		// "/api/sequencer/capture/confirm" resolves by longest match to "/api/sequencer/capture/",
		// which is riskRead — the read subtree under an attack route. Ungated, so the mint fell
		// through to the main mux, which has no such route, and the answer was 405. A gated route
		// whose mint endpoint 405s is a gate that forbids the route.
		minted := confirmPatternFor(r.URL.Path)
		if minted != r.URL.Path {
			if _, risk, ok := routeRiskFor(minted); ok && needsConfirmation(risk) {
				confirmMux.ServeHTTP(w, r)
				return
			}
		}
		pattern, risk, ok := routeRiskFor(r.URL.Path)
		// Reads and safe methods are not gated: a GET on a gated route is a read of state the gate
		// is protecting, not the protected act itself — /api/scope is riskScope and answers GET
		// with the scope list. Gating reads would mean the console could not display the thing
		// the operator is about to confirm, which is the dialog this gate exists to back up.
		if !ok || !needsConfirmation(risk) || !methodMutates(r.Method) {
			h.ServeHTTP(w, r)
			return
		}
		// The cross-site gate is OUTER (see setupRoutes), so by the time a request is here it has
		// already been shown to be same-origin. That is what lets this refusal be specific — it can
		// name the route and the header, because reaching this line already means the caller is not
		// a hostile page. The ordering is load-bearing and the tests below hold it: with the gates
		// the other way round, a cross-site caller received this 428 and learned which header to
		// try next.
		token := r.Header.Get(ConfirmHeader)
		if token == "" {
			s.refuseUnconfirmed(w, pattern, risk, true)
			return
		}
		// The body is read here, in full, so the call can be compared with the one the token was
		// minted for, and then handed to the route unchanged. Only when a token is presented: an
		// unconfirmed call is refused without the gate reading a byte of it. The cap is the server's
		// own request cap, so the gate buffers nothing a handler could not have been sent anyway.
		call, body, err := bindingOfRequest(r)
		if err != nil {
			// The token is burned as a spend would burn it: a presented token whose call cannot be
			// read — or cannot be read one way only — is not left live for a second attempt.
			s.confirms.burn(token)
			if errors.Is(err, errAmbiguousBody) {
				http.Error(w, "refused: "+err.Error(), http.StatusBadRequest)
				return
			}
			http.Error(w, "could not read the request body to check it against its confirmation: "+err.Error(), http.StatusRequestEntityTooLarge)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(body))
		if !s.confirms.spend(token, pattern, call) {
			s.refuseUnconfirmed(w, pattern, risk, false)
			return
		}
		h.ServeHTTP(w, r)
	})
}

// methodMutates reports whether a verb can change state or cause egress.
//
// The safe set is spelled out rather than the unsafe one, so a verb Go adds later is treated as
// mutating until someone says otherwise. A new HTTP method defaulting to "harmless" is the wrong
// direction for a gate that stands in front of an attack route.
func methodMutates(method string) bool {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodTrace:
		return false
	default:
		return true
	}
}

// refuseUnconfirmed answers a gated call that carried no usable confirmation.
//
// 428 Precondition Required rather than 403: the request is well-formed and may well be
// permitted, it is missing a precondition. 403 would tell a caller "no" about a thing it has not
// tried yet, and 401 would imply an authentication problem this console does not have.
func (s *Server) refuseUnconfirmed(w http.ResponseWriter, pattern string, risk riskClass, missing bool) {
	detail := "this route needs an explicit confirmation of this exact call; POST " + strings.TrimSuffix(pattern, "/") +
		`/confirm with {"method":…,"url":…,"body":…} describing the call to get one`
	if !missing {
		detail = "the confirmation for this call is not valid: it has expired, was already used, or was issued for a different route or a different request (method, path, query or body)"
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusPreconditionRequired)
	_ = json.NewEncoder(w).Encode(map[string]any{
		"error":        detail,
		"route":        pattern,
		"risk":         string(risk),
		"confirm_with": ConfirmHeader,
		"expires_in":   int(ConfirmTTL.Seconds()),
	})
}

// handleConfirm mints a one-time confirmation for one concrete call to the route named in the path.
//
// Registered as a SUBTREE under each gated pattern, so the pattern is taken from the request rather
// than from a table entry — a caller cannot be handed a token for one route and spend it on
// another, because the token is issued FOR this path and the gate spends it against this path.
//
// The body describes the call the token will authorise (confirmCall), and the answer echoes back
// what the server resolved it to (confirmPreview) — the request an approver is agreeing to, as the
// gate will compare it, not as the caller summarised it. Before burpsy-react-ui-e0yq the mint took
// no body: the approver signed a route name, and the token it produced authorised any request to
// that route. A mint with no call described is refused rather than defaulted to "any call": an
// unbound token is exactly the thing this binding removes.
//
// The gate does not consult this handler's response for anything but the token. A caller that can
// POST here without a human present has the same problem as a caller that can set the header
// itself, and no server-side scheme fixes that on its own: it is why the confirm endpoint is the
// right place for the console's own auth to sit, and why that auth is a separate bead (console
// auth, not this one). What this gate DOES guarantee is that the dangerous call is never reached
// by accident, never reached by a tool acting on the operator's earlier, unrelated instruction, and
// never reached by a request other than the one that was shown.
func (s *Server) handleConfirm(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		http.Error(w, "confirmation is minted with POST", http.StatusMethodNotAllowed)
		return
	}
	// The suffix is stripped and the trailing slash restored, so a token is issued against the SAME
	// pattern string the gate spends it against. A subtree pattern registered as "/api/x/" and a
	// request for "/api/x/confirm" would otherwise mint against "/api/x" and never match.
	pattern := confirmPatternFor(r.URL.Path)
	_, risk, ok := routeRiskFor(pattern)
	if !ok {
		http.Error(w, "no such route", http.StatusNotFound)
		return
	}
	if !needsConfirmation(risk) {
		http.Error(w, "this route does not require confirmation", http.StatusBadRequest)
		return
	}
	var desc confirmCall
	if err := requestJSON(w, r, http.MaxBytesReader(w, r.Body, maxConfirmDescriptionBytes)).Decode(&desc); err != nil {
		msg := "describe the call this confirmation is for: " + `{"method":"POST","url":"` + pattern + `…","body":"<the exact request body>"}`
		if !errors.Is(err, io.EOF) {
			msg += " (" + err.Error() + ")"
		}
		http.Error(w, msg, http.StatusBadRequest)
		return
	}
	call, err := desc.resolve(pattern)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	token, err := s.confirms.issue(pattern, call)
	if err != nil {
		http.Error(w, "could not mint a confirmation: "+err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	// A preview may carry request content; it is the caller's own request echoed back, and it is not
	// a response anything should cache.
	w.Header().Set("Cache-Control", "no-store")
	_ = json.NewEncoder(w).Encode(confirmMinted{
		ConfirmWith: ConfirmHeader,
		Token:       token,
		Route:       pattern,
		ExpiresIn:   int(ConfirmTTL.Seconds()),
		Binding:     call.digest(),
		Call:        call.preview(),
	})
}

// routeRiskFor resolves a request path to its manifest pattern and risk class.
//
// Longest-prefix, because ServeMux does the same thing and the gate has to agree with it: a gate
// that resolved "/api/audit/" to "/api/audit" would read a different risk for the same route the
// mux routed. "{param}" segments (burpsy-react-ui-fxxm) match one non-empty segment each, the way
// the mux's own wildcards do; between two patterns that match, the one with more literal text
// wins, which is the mux's literal-beats-wildcard rule restated for a table lookup.

		t.Errorf("no report rendered: %s", rec.Body.String()[:ui2Min(300, rec.Body.Len())])
	}
}

// TestUI2CollaboratorMintConfirmStep: the payload route is riskEgress, which the confirmation
// gate does not cover, so there is no token-mint endpoint for it — the two-step confirm is
// ui2-local. The first POST shows the exact call; only confirmed=1 dispatches.
func TestUI2CollaboratorMintConfirmStep(t *testing.T) {
	s := newTestServer()
	req := httptest.NewRequest(http.MethodPost, "/ui2/collaborator/mint", strings.NewReader("count=1"))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	rec := httptest.NewRecorder()
	s.mux.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("mint page = %d", rec.Code)
	}
	body := rec.Body.String()
	if !strings.Contains(body, "Confirm mint") {
		t.Errorf("first POST did not render the confirm step: %s", body[:ui2Min(300, len(body))])
	}
	if !strings.Contains(body, "POST /api/collaborator/payload") {
		t.Errorf("confirm step does not name the exact call: %s", body[:ui2Min(300, len(body))])
	}
	if !strings.Contains(body, `name="mint_id"`) {
		t.Errorf("confirm form does not carry the server-held mint id: %s", body[:ui2Min(300, len(body))])
	}
	if strings.Contains(body, `name="token"`) {
		t.Errorf("confirm step still asks the gate for a token — that endpoint 404s for riskEgress")
	}

	// The confirm POST spends the held call; with no interaction server configured the
	// handler answers with the API's error rendered, not a broken page.
	mintID := extractHiddenInput(t, body, "mint_id")
	req2 := httptest.NewRequest(http.MethodPost, "/ui2/collaborator/mint", strings.NewReader("mint_id="+mintID))
	req2.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	rec2 := httptest.NewRecorder()
	s.mux.ServeHTTP(rec2, req2)
	if rec2.Code != http.StatusOK {
		t.Fatalf("confirmed mint page = %d", rec2.Code)
	}
	if strings.Contains(rec2.Body.String(), "Confirm mint") {
		t.Errorf("confirmed POST rendered the confirm step again instead of dispatching")
	}
}

func TestUI2IntruderPagesAreRegistered(t *testing.T) {
	s := newTestServer()
	for _, p := range []string{"/ui2/intruder", "/ui2/sequencer", "/ui2/collaborator"} {
		if rec := getUI2(t, s, p); rec.Code != http.StatusOK {
			t.Errorf("GET %s = %d", p, rec.Code)
		}
		t.Fatal("the call reached the confirmation gate without a selection")
	}
}

// TestUI2CollaboratorConfirmSpendsTheHeldCall: the confirm form carries only the mint id; the
// dispatched body is the one the server held when the preview rendered. A count edited between
// preview and confirm cannot change what runs, and the id is single-use.
func TestUI2CollaboratorConfirmSpendsTheHeldCall(t *testing.T) {
	s := newTestServer()

	form := "count=2"
	req := httptest.NewRequest(http.MethodPost, "/ui2/collaborator/mint", strings.NewReader(form))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	rec := httptest.NewRecorder()
	s.mux.ServeHTTP(rec, req)
	frag := rec.Body.String()
	// html/template escapes the preview's quotes (&#34;) in the raw fragment.
	if !strings.Contains(frag, `&#34;count&#34;:2`) {
		t.Fatalf("preview does not show the call: %s", frag[:ui2Min(300, len(frag))])
	}
	id := extractHiddenInput(t, frag, "mint_id")
	v, ok := s.ui2Mints.Load(id)
	mint, isMint := v.(ui2PendingMint)
	if !ok || !isMint || string(mint.body) != `{"count":2}` {
		got, _ := v.(ui2PendingMint)
		t.Fatalf("held call: present=%v body=%q, want the previewed {\"count\":2}", ok, got.body)
	}

	// Confirm, with the form's count tampered: it is not even parsed on this path.
	form2 := "mint_id=" + id + "&count=20"
	req2 := httptest.NewRequest(http.MethodPost, "/ui2/collaborator/mint", strings.NewReader(form2))
	req2.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	rec2 := httptest.NewRecorder()
	s.mux.ServeHTTP(rec2, req2)
	body2 := rec2.Body.String()
	// The API's own refusal (no channel configured) proves the held call was dispatched.
	if !strings.Contains(body2, "no out-of-band interaction channel is configured") {
		t.Fatalf("the held call was not dispatched: %s", body2[:ui2Min(300, len(body2))])
	}

	// Single-use: the same id cannot confirm twice.
