	ClientIP      string `json:"client_ip"`
	ClientIPMeans string `json:"client_ip_means"`
	AtMs          int64  `json:"at_ms"`
	QType         string `json:"q_type,omitempty"`
	Payload       string `json:"payload,omitempty"`
