		if errText != "" {
			m.HealthError = errText
		} else {
			m.Health = &report
		}
		s.ui2CollabRender(w, r, m)
		return
	}
	m := s.ui2CollabPage(r)
	body := []byte("{}")
	id, _, errText := s.ui2CollabHold("health", http.MethodPost, "/api/collaborator/health", body)
	if errText != "" {
